-- Machining - Step Drilling
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Machining - Step Drilling$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - Step Drilling$q$, 'process', 'single', false, true, true, $q$A counterbore or a hole's larger step, drilled as the Machining calculator workbook's Step Drilling sheet times it: n = 1000 v / (pi D) at the step's diameter, capped at the machine's spindle limit; time = (step depth + 10 mm) / (feed x n), rounded up to whole seconds. Cutting speed and feed of the step diameter's band from the workbook's drilling and reaming table; drill price and life from the sheet. (It replaces a counterboring time from tblCounterboring, and 8 s a hole when that had no row.)$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$A counterbore or a hole's larger step, drilled as the Machining calculator workbook's Step Drilling sheet times it: n = 1000 v / (pi D) at the step's diameter, capped at the machine's spindle limit; time = (step depth + 10 mm) / (feed x n), rounded up to whole seconds. Cutting speed and feed of the step diameter's band from the workbook's drilling and reaming table; drill price and life from the sheet. (It replaces a counterboring time from tblCounterboring, and 8 s a hole when that had no row.)$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
